  (1, 'דניאל לוי', 7, 'guard', 184, '138920c8-cd46-4248-a75a-575aa8fb1389', 'המנוע', 'קפטן ורכז', 'מכתיב את הקצב ולא מוותר על אף כדור.', '🎯 פול-אפ מחצי מרחק', '😂 חזרה להגנה', '״תנו לי את הכדור.״', 'בגובה 1.84, עם מספר 7 ובלי שום כוונה למסור... הקפטן, המנוע!', 'המנוע', true, 0),
  (2, 'רועי כהן', 11, 'guard', 180, 'f85b1014-8ddb-41d4-a8d9-e8d938b7f85b', 'הקוסם', 'מוסר ראשי', 'רואה מסירות שאף אחד אחר לא רואה.', '🪄 מסירות ללא מבט', '🧱 זריקות עונשין', '״זה היה פאול.״', 'הוא מוסר בלי להסתכל וזורק עונשין בלי לקלוע... הקוסם!', 'בליבלי', true, 1),
  (3, 'עומר מזרחי', 23, 'center', 201, '226edb00-4128-4b00-a94b-294bd403226e', 'החומה', 'עוגן בצבע', 'שולט בריבאונד ומפחיד כל מי שנכנס לצבע.', '🧱 ריבאונד התקפה', '🐌 מעבר להתקפה', '״מי לקח לי את הריבאונד?״', '2.01 של בטון מזוין. אל תיכנסו לצבע... החומה!', 'אין_כניסה', true, 2),
  (4, 'איתי פרץ', 3, 'forward', 192, '452448ec-4741-472c-a06e-406e5eff4524', 'הצלף', 'קלע מהספסל', 'הצלף של הקבוצה – אל תשאירו אותו פנוי בפינה.', '🎯 שלשות מהפינה', '🛡 הגנה אחד על אחד', '״שחרר אותי בפינה.״', 'מהפינה השמאלית, ורק מהפינה השמאלית... הצלף!', 'רק_פינה', true, 3),
  (5, 'נועם אברהם', 14, 'forward', 195, '26765f20-baad-4520-a1cb-81cbf6e32676', 'הטנק', 'פורוורד פיזי', 'נכנס לסל עם כל הכוח ולא מפחד ממגע.', '💪 חדירות לסל', '🎯 קליעה מבחוץ', '״עוד פעם אחת חזק.״', 'תזיזו את הכיסאות מהקו, הוא לא בולם... הטנק!', 'דרך_הקיר', true, 4),
  (6, 'יונתן ביטון', 5, 'guard', 178, '6bfe0534-f143-4cf4-ae57-ee5734976bfe', 'הברק', 'מגן מהיר', 'הכי מהיר במגרש, במיוחד במתפרצות.', '⚡ מתפרצות', '⏰ מגיע אחרון לאימון', '״אני כבר בדרך!״', 'הכי מהיר במגרש, הכי איטי להגיע לאימון... הברק!', 'כבר_בדרך', true, 5),
  (7, 'אלון שפירא', 32, 'center', 204, '7dbe1298-95dc-4318-af00-5f00f5cb7dbe', 'המגדל', 'סנטר מחליף', 'גבוה, רגוע וחוסם זריקות כמו תחביב.', '🚫 חסימות', '🏃 כושר גופני', '״רק עוד שתי דקות.״', '2.04 ממטר, ושתי דקות של כושר... המגדל!', 'לא_בבית_שלי', true, 6),
  (8, 'גיא דהן', 9, 'forward', 190, '790dd5e3-4a6e-4cf3-aaa1-6aa1d15a790d', 'הדבק', 'מגן על השחקן הטוב של היריבה', 'עובד קשה בהגנה ולוקח כל משימה.', '🛡 הגנה לוחצת', '🏀 כדרור ביד חלשה', '״תן לי את הכי טוב שלהם.״', 'השחקן הכי טוב שלהם כבר מתחיל להזיע... הדבק!', 'סופר_גלו', true, 7),
  (9, 'עידו קפלן', 21, 'guard', 183, '1e7a5a59-3e6b-4889-a0db-f0db88d41e7a', 'הפרופסור', 'מנתח המשחק', 'תמיד יודע מה היריבה הולכת לעשות.', '🧠 אינטליגנציית משחק', '🏋️ אתלטיות', '״ראיתי את זה בווידאו.״', 'צפה בשלוש שעות וידאו על היריבה, קפץ פעם אחת... הפרופסור!', 'ראיתי_בווידאו', true, 8),
  (10, 'תומר אזולאי', 8, 'forward', 188, '422e7a44-f688-4d04-a323-5323bfe7422e', 'השף', 'אחראי הפיצה', 'מביא אנרגיה – ובעיקר את הפיצה אחרי המשחק.', '🍕 מורל הקבוצה', '🎯 עונשין בלחץ', '״מי מזמין הפעם?״', 'אחראי על המורל, האנרגיה, ובעיקר על המגש המשפחתי... השף!', 'תוספת_זיתים', true, 9);
