insert into public.exercises (id, title, category, description, instructions, coaching_points, duration_minutes, difficulty, video_media_id, thumbnail_media_id, image_media_id, is_published, sort_order) overriding system value values
  (1, 'פיק אנד רול מרכזי', 'pick_and_roll', 'הסנטר עולה לחסום לרכז בראש הקשת — חדירה, מסירה לגולל או זריקה.', array['הרכז מכדרר לראש הקשת, ארבעה שחקנים פרוסים.', 'הסנטר עולה ושם חסימה על המגן של הרכז.', 'הרכז יוצא מהחסימה לכיוון הסל, הסנטר מתגלגל לטבעת.']::text[], array['ההגנה מחליפה: מסירה לסנטר מול השומר הנמוך', 'הגבוה יוצא גבוה: מסירה לגולל', 'הגבוה נשאר מאחור: זריקה מעל החסימה']::text[], null, 'easy', '0b02e199-df7e-4bc9-ac4e-9c4e22940b02', '5882803a-394c-421a-a225-3225b6995882', null, true, 0),
  (2, 'פיקנרול ספרדי', 'pick_and_roll', 'פיק אנד רול מרכזי עם חסימה אחורית לגבוה המתגלגל — מייצר שלשה או סל קל.', array['הסנטר עולה לפיק אנד רול עם הרכז.', 'קלעי מהכנף שם חסימה אחורית למגן של הסנטר.', 'הסנטר מתגלגל לסל, הקלעי יוצא מיד לשלשה.']::text[], array['תזמון החסימה האחורית', 'הרכז מחכה לשתי החסימות', 'אם הגבוה נעזר: מסירה מהירה לקלעי שיצא']::text[], null, 'hard', '9ad55020-d73b-4620-a2a1-62a19be39ad5', '0ded0560-100b-4760-a156-21561ea30ded', null, true, 1),
  (3, 'הורנס', 'set_play', 'שני גבוהים בגובה קו העונשין ושני קלעים בפינות — פיק אנד רול לכל צד.', array['שני הגבוהים עומדים בקצוות קו העונשין.', 'הרכז בוחר צד ויוצא מחסימה.', 'הגבוה השני יוצא החוצה לזריקה או למסירה גבוה-נמוך.']::text[], array['רווחים מלאים בפינות', 'קריאת ההגנה לפני הבחירה', 'הגבוה שלא חסם נשאר מאיים']::text[], null, 'medium', null, 'dc189c93-2c9a-4ca3-a281-8281d84adc18', null, true, 2),
  (4, 'פלאפי', 'set_play', 'רצף חסימות לקלעי שיוצא מתחת לסל — זריקה מהירה מהכנף.', array['הקלעי מתחיל מתחת לסל.', 'שני גבוהים שמים חסימות משני הצדדים.', 'הקלעי בוחר צד ויוצא לזריקה.']::text[], array['לקרוא את המגן ולבחור צד', 'כתף לכתף עם החוסם', 'רגליים מוכנות לזריקה לפני המסירה']::text[], null, 'medium', null, '53af8642-66ff-45a2-ac30-dc30b93153af', null, true, 3),
  (5, 'מסך מעלית', 'set_play', 'שני שחקנים נסגרים כמו דלת מעלית אחרי שהקלעי עובר — שלשה פתוחה.', array['שני שחקנים עומדים צמודים עם רווח ביניהם.', 'הקלעי רץ דרך הרווח לקשת.', 'השניים נסגרים מאחוריו וחוסמים את המגן.']::text[], array['לסגור את הדלת בזמן', 'הקלעי רץ מהר בין החוסמים', 'המוסר מוכן לפני שהקלעי יוצא']::text[], null, 'hard', null, 'c12fd589-9c6f-44b9-a5b8-35b83204c12f', null, true, 4),
  (6, 'מושן ארבע בחוץ', 'motion', 'ארבעה בחוץ ואחד בפנים — חיתוכים, מסירות וחסימות רחוקות מהכדור.', array['מוסרים וחותכים לסל אחרי כל מסירה.', 'השחקן שבפינה ממלא את המקום הריק.', 'הגבוה עולה לחסימה רחוקה כשאין חיתוך.']::text[], array['לא לעמוד במקום יותר משתי שניות', 'רווח של ארבעה מטרים בין שחקנים', 'המגן נצמד: חיתוך אחורי']::text[], null, 'medium', null, '974abed8-3f4a-4b58-a541-d541478b974a', null, true, 5),
  (7, 'הכנסה מתחת לסל - קופסה', 'inbound', 'ארבעה שחקנים בריבוע מול המכניס — חסימה כפולה לקלעי.', array['ארבעה שחקנים בריבוע בגובה הצבע.', 'הגבוהים מלמטה חוסמים לקלעים שלמעלה.', 'קלעי אחד לפינה, השני לסל.']::text[], array['המכניס קורא לתחילת המהלך', 'חסימות חזקות ויציבות', 'אופציה אחרונה: מסירה בטוחה לרכז']::text[], null, 'easy', null, '34426d02-2ee1-4062-a486-0486ae713442', null, true, 6),
  (8, 'מתפרצת בשלוש מסלולים', 'fast_break', 'אחרי ריבאונד: רכז באמצע, כנפיים רצים רחב — יתרון מספרי לסל.', array['הריבאונדר מוסר מהר לרכז.', 'הכנפיים רצים בצדדים לפינות.', 'הרכז מחליט בקו העונשין: מסירה או סיום.']::text[], array['לרוץ רחב, לא באמצע', 'מסירה ראשונה בתוך שתי שניות', 'הגבוה הראשון רץ ישר לצבע']::text[], null, 'easy', null, '2cc7e412-8cdf-4272-a216-32163a012cc7', null, true, 7),
  (9, 'התקפה מול אזורית 2-3', 'zone_offense', 'שחקן בקו העונשין ותזוזת כדור מהירה — שוברים את האזורית מבפנים.', array['גבוה עולה לקו העונשין לקבל כדור.', 'קלעים בפינות ובכנפיים.', 'מהקו: זריקה, מסירה לפינה או לגבוה שמתחת לסל.']::text[], array['לעמוד ברווחים בין המגנים', 'להעביר כדור מצד לצד מהר', 'פייק מסירה לפני כל מסירה']::text[], null, 'medium', null, 'd1b13bb2-6fff-4812-ac81-7c813861d1b1', null, true, 8),
  (10, 'זריקה אחרונה - בידוד', 'late_game', 'עשר שניות לסיום: מפנים צד לשחקן הטוב ביותר שלנו.', array['ארבעה שחקנים יורדים לצד החלש.', 'השחקן המוביל מתחיל לכדרר עם שמונה שניות.', 'חדירה או זריקה עם שלוש שניות על השעון.']::text[], array['לא למהר — לנצל את השעון', 'אם יש עזרה: מסירה לפינה', 'ריבאונד התקפה לשני גבוהים']::text[], null, 'medium', 'e84fa673-0173-4083-ac53-4c531e6ae84f', '3d008300-9045-4300-a6c5-56c5dc033d00', null, true, 9);
